import json,re,hashlib,pathlib
P=pathlib.Path(__file__).parent
src=json.loads((P/'source.json').read_text())
by={a['number']:a for a in src}
rows=[]; report=[]
POLICY='editorial_direction_2026_10_19'
TRANS="Les dispositions transitoires du V de l'article L. 302-5 s'appliquent."
def base(n):
 a=by[n]; return (a.get('previous_draft') or {}).get('proposed_xml') or a['source_xml'].strip()
def rep(s,old,new,count=1):
 assert s.count(old)==count,(old,s.count(old),count)
 return s.replace(old,new)
def para(s,index,new):
 ps=list(re.finditer(r'<p\b[^>]*>.*?</p>',s,re.S));m=ps[index];return s[:m.start()]+new+s[m.end():]
def add(n,s,reason,notes,removed=None):
 a=by[n];assert s!=base(n),n
 row={k:a[k] for k in ['code_id','source_id','source_sha256','number']}
 row.update(proposed_xml=s,reason=reason,review_notes=notes)
 if removed:row.update(change_type='normative_reduction',reform_policy_id=POLICY,removed_provisions=removed)
 rows.append(row);report.append({'number':n,'treatment':'modified','reason':reason,'review_notes':notes,'removed_provisions':removed or []})
def definition(n):
 s=base(n); count=s.count("à l'article L. 302-5")
 assert count>0
 s=s.replace("à l'article L. 302-5","au IV de l'article L. 302-5")
 add(n,s,"Coordination de l'abolition des quotas communaux : les renvois définissant le logement social visent expressément le IV autonome de L. 302-5. Les autres règles de l'article et les réécritures antérieures compatibles sont intégralement conservées.",f"{count} renvoi(s) définitionnel(s) précisé(s). Aucun objectif communal, inventaire SRU ou pouvoir de carence n'est institué. Les contrôles, aides, conditions locatives et limites d'activité indépendants du quota demeurent. Notes source lues intégralement : "+(by[n]['source_notes_xml'] or 'néant.'))
for n in ['L253-8','L302-16','L342-2','L342-14','L411-2']:definition(n)
n='L301-5-1-3';s=base(n)
start=s.index("Lorsque l'autorité organisatrice de l'habitat a signé")
s=s[:start]+"Lorsque l'autorité organisatrice de l'habitat a signé une convention pluriannuelle mentionnée au premier alinéa du I de l'article 10-3 de la loi n° 2003-710 du 1er août 2003 d'orientation et de programmation pour la ville et la rénovation urbaine, cette convention peut, par dérogation au deuxième alinéa du I de l'article 9-1 de la même loi, prévoir que les logements locatifs sociaux financés dans le cadre du nouveau programme national de renouvellement urbain sont produits dans toute commune membre de l'établissement public de coopération intercommunale reconnu autorité organisatrice de l'habitat, y compris hors de l'unité urbaine du quartier concerné. Le choix de localisation tient compte des besoins de logement et des caractéristiques de l'opération ; il ne dépend d'aucun taux communal de logements sociaux ni d'une obligation de rattrapage. "+TRANS+"</p>"
add(n,s,"Suppression de la priorité fondée sur le rattrapage SRU et de la condition d'absence de commune déficitaire dans l'unité urbaine. La convention ANRU conserve une faculté territoriale autonome à l'intérieur de l'EPCI.","Les trois premiers alinéas, les conditions de reconnaissance, le retrait dans l'année et la consultation fiscale sur demande sont conservés. Extension explicitée : l'option conventionnelle de localisation hors unité urbaine ne dépend plus d'une liste SRU. Le programme ANRU et ses financements demeurent distincts. Les articles 9-1 et 10-3 de la loi n° 2003-710 restent hors corpus et doivent être coordonnés dans leur champ propre.",["Priorité de reconstitution de l'offre au bénéfice des seules communes soumises au rattrapage de L. 302-8 et condition d'absence de telles communes dans l'unité urbaine."])
n='L302-4';s=base(n);s=s[:s.index('<p>II. -')]+"<p>II. - Les obligations de modification du programme local de l'habitat et les réaffectations de prélèvements qui reposaient exclusivement sur les quotas communaux de logements sociaux sont abrogées. "+TRANS+"</p>"
add(n,s,"Suppression intégrale de la procédure du II imposant d'adapter le PLH aux quotas SRU et de la réaffectation sanctionnant son absence. Le I, relatif aux modifications autonomes du PLH, demeure entier.","Les huit paragraphes du I sont repris sans changement : économie générale, trois motifs, extension inférieure au cinquième, avis réputé donné sous deux mois, approbation et adaptation selon CU L. 300-6-1. Aucune modification de PLH en cours n'est exigée pour rétablir le quota. L302-4-1 et ses renvois par alinéa doivent être contrôlés séparément ; le renvoi préexistant au quatrième alinéa apparaît déjà ambigu dans le corpus.",["Modification obligatoire du PLH dans les deux ans pour intégrer les obligations communales de L. 302-5 et suivants, exigences préfectorales et suspension du caractère exécutoire liées à ces obligations.","Réaffectation des prélèvements SRU en cas de refus ou de défaut de modification du PLH pour le rattrapage communal."])
n='L353-15';s=base(n);s=rep(s,"<p>VII. - Le VI du présent article ne s'applique pas aux immeubles situés dans une commune mentionnée aux I ou II de l'article L. 302-5.</p>","<p>VII. - Le VI s'applique sans condition tenant au taux communal de logements sociaux. "+TRANS+"</p>")
add(n,s,"Suppression de l'exclusion territoriale SRU empêchant les opérations de vente ou de changement d'usage prévues par convention ANRU. Les autorisations de l'opération, garanties de financement et protections des occupants sont maintenues.","Les I à VI restent intégralement ceux de la proposition antérieure. Trois offres, logement spécialement conçu, six mois, cinq logements, départ du dernier locataire, accords du maire et des garants et exigences d'ancienneté, d'habitabilité et d'énergie conservés. Le VII étend explicitement la faculté ANRU aux anciennes communes SRU ; il n'emporte aucune résiliation automatique de convention ni éviction d'occupant. L'ambiguïté préexistante du III entre troisième offre et logement spécialement conçu reste signalée.",["Exclusion des immeubles situés dans les communes des I ou II de L. 302-5 du mécanisme conventionnel ANRU de vente ou de changement d'usage du VI."])
n='L371-4';s=rep(base(n),"1° Les articles L. 300-1 et L. 302-7 ne s'appliquent pas ;","1° L'article L. 300-1 ne s'applique pas ;")
add(n,s,"Suppression du renvoi devenu sans objet à l'inapplicabilité de l'ancien prélèvement SRU à Mayotte, celui-ci étant aboli nationalement. Toutes les autres adaptations territoriales sont conservées.","L'exception propre à L. 300-1 demeure : la réforme SRU ne crée pas ici un régime DALO différent. Les neuf subdivisions, dates de 2014 et 2015, pension et allocations, et adaptations foncières sont maintenues. La note d'entrée en vigueur issue de la loi n° 2025-797 est préservée dans le dossier source ; elle ne date pas la réforme proposée. Le V proposé de L. 302-5 n'ouvre aucune créance SRU antérieure qui n'aurait pas été légalement due à Mayotte.")
n='L411-5';report.append({'number':n,'treatment':'retained_no_new_draft','reason':'Le renvoi vise déjà le 2° du IV de L302-5 et définit les logements maintenus sous plafond pendant six ans après convention. Protection locative indépendante du quota, intégralement conservée. Aucune nouvelle réécriture comptée.'})
n='L411-5-1';s=base(n);s=para(s,3,"<p>Le non-renouvellement ne requiert aucun avis conforme du maire ou du représentant de l'État au titre d'un taux communal de logements sociaux ou d'une obligation de rattrapage. "+TRANS+"</p>")
add(n,s,"Suppression des deux avis conformes et de la saisine trente mois avant échéance uniquement fondés sur le quota SRU. Conservation des informations et notifications protégeant les locataires et des notifications au maire et au préfet.","Les quatre catégories d'information au locataire, le seuil de plus de dix logements et le préavis de deux ans avec prévision de loyer sont conservés. Le troisième alinéa de notification aux autorités demeure. Le cinquième alinéa réglementaire n'autorise pas à rétablir l'avis conforme supprimé. Coordination directe communiquée à l'agent chargé de D411-2/R411-3, notamment pour le délai de six mois rattaché à l'ancien avis.",["Avis conformes du maire et du préfet et saisine trente mois avant expiration de la convention seulement parce que la commune est soumise ou serait soumise au régime de quota SRU."])
n='L411-10';s=base(n);s=rep(s,"<p>Pour les personnes morales mentionnées à l'article L. 302-6, la transmission des informations nécessaires à la tenue du répertoire vaut production de l'inventaire prévu à cet article.</p>","<p>La tenue du répertoire ne crée aucune obligation d'inventaire, de transmission ou de collecte au titre des anciens quotas communaux de logements sociaux.</p>")
add(n,s,"Suppression de l'équivalence avec l'inventaire SRU aboli, sans supprimer le répertoire autonome ni la transmission valant inventaire pour la dotation de solidarité urbaine.","Les données, destinataires, anonymisation, cinq catégories de bailleurs, détention de 99 %, sanction de 1 000 € après mise en demeure et affectation au FNAP sont conservés pour le répertoire indépendant. L. 2334-17 CGCT doit être examiné dans son régime distinct ; l'équivalence le visant est conservée. L'imprécision préexistante du rattachement grammatical de la convention aux catégories de destinataires n'est pas résolue ici. Les deux notes historiques de 2015/2018/2019 restent applicables à leur objet.",["Équivalence entre la transmission au répertoire des logements sociaux et l'inventaire communal SRU prévu à L. 302-6, qui ne doit plus générer d'obligation supprimée."])
n='L444-2';s="<p>Le logement pris à bail doit être vacant depuis au moins un an. Il doit appartenir à une ou plusieurs personnes physiques ou à une société civile immobilière constituée exclusivement entre parents et alliés jusqu'au quatrième degré inclus.</p><p>La conclusion du contrat de prise à bail n'est pas subordonnée à l'accord du maire en raison du taux communal de logements sociaux. "+TRANS+"</p>"
add(n,s,"Suppression de l'accord du maire déclenché par le seuil communal de 20 %. Les conditions autonomes de vacance et de propriété du logement restent intégrales.","L'accord communal n'est pas étendu aux communes anciennement situées sous le seuil. Vacance d'au moins un an et SCI exclusivement familiale jusqu'au quatrième degré maintenues. Les contrats régulièrement conclus et leurs clauses privées ne sont pas automatiquement réécrits ; leur modification suit le droit commun. L444-1/L444-3 et les dispositions réglementaires du bail doivent être contrôlés pour un éventuel renvoi à l'accord supprimé.",["Accord du maire sur le contrat de prise à bail en fonction du seuil de 20 % de logements sociaux au 1er janvier de la pénultième année et de l'ancien décompte SRU des résidences principales."])
(P/'candidates.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
(P/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print(len(rows),'candidats ;',len(report),'articles examinés')
